              "html": "The letters أَلِفٌ، وَاوٌ and يَاءٌ are known as حَرْفُ الْعِلَّةِ, weak letters. If a verb has a حَرْفُ الْعِلَّةِ and does not end in a نُوْنُ الضَّمِيْرِ or نُوْنُ الْإِعْرَابِ, it will undergo slight changes to make pronunciation easier.",
